import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse(`{"title":"Create Compare Item","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-compare-item","title":"Add Product to Compare List","description":"Add a product to the authenticated customer's comparison list.","request":"POST /api/shop/compare_items\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer <accessToken>\\n\\n{\\n  \\"productId\\": 1\\n}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 155,\\n  \\"createdAt\\": \\"2026-08-07T15:56:42+05:30\\",\\n  \\"updatedAt\\": \\"2026-08-07T15:56:42+05:30\\",\\n  \\"product\\": \\"/api/shop/products/126\\",\\n  \\"customer\\": \\"/api/shop/customers/122\\"\\n}\\n","commonErrors":[{"error":"400 Bad Request — Product ID is required","cause":"productId was missing from the body","solution":"Send productId as a numeric product ID"},{"error":"400 Bad Request — This product is already in your comparison list","cause":"The customer already added this product","solution":"Read the list first, or treat the 400 as \\"already added\\" in the UI"},{"error":"404 Not Found — Product not found","cause":"No product carries that ID","solution":"Use an ID returned by the product endpoints"},{"error":"403 Forbidden","cause":"No customer Bearer token was sent","solution":"Log the customer in; guests cannot hold a comparison list"}]}]},"headers":[],"relativePath":"api/rest-api/shop/compare/create.md","filePath":"api/rest-api/shop/compare/create.md"}`),s={name:"api/rest-api/shop/compare/create.md"};function d(i,e,n,c,l,p){return o(),a("div",null,e[0]||(e[0]=[r(`<h1 id="create-compare-item" tabindex="-1">Create Compare Item <a class="header-anchor" href="#create-compare-item" aria-label="Permalink to &quot;Create Compare Item&quot;">​</a></h1><p>Add a product to the authenticated customer&#39;s comparison list.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/compare_items</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Customer Bearer token (<code>Bearer &lt;accessToken&gt;</code>)</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;productId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>productId</code></td><td>integer</td><td>Yes</td><td>ID of the product to add to the compare list.</td></tr></tbody></table><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><p>The created comparison row. Product and customer come back as <strong>path references, not nested objects</strong> — no product details are included.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>New comparison row ID. Keep it for <a href="/api/rest-api/shop/compare/delete.html">Delete</a>.</td></tr><tr><td><code>product</code></td><td>string</td><td>Path of the compared product, e.g. <code>/api/shop/products/126</code>.</td></tr><tr><td><code>customer</code></td><td>string</td><td>Path of the owning customer.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li>Adding a product that is already on the list is <strong>rejected</strong> with <code>400</code>; it is not a silent no-op, and there is no toggle endpoint here as there is for the wishlist.</li><li>The list is not channel-scoped, so an item added on one channel appears on all of them.</li><li>Any product type can be added; comparison reads the products separately, so no option choices are stored.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Add to compare&quot; on a product card</strong> — post the product ID and keep the returned row ID so the same control can remove it again.</li><li><strong>Build a comparison set before rendering</strong> — add each product as it is marked, then fetch all of them at once for the comparison table.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Handle <code>400</code> as &quot;already added&quot;</strong> — the message names that case explicitly, and it is the common outcome of a double tap.</li><li><strong>Do not render from this response</strong> — it carries no name, price, or attributes.</li><li><strong>Cap the set client-side</strong> — the API imposes no limit, and a comparison table with a dozen columns is unusable.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/compare/list.html">Get Compare Items</a> — the customer&#39;s comparison rows</li><li><a href="/api/rest-api/shop/compare/delete.html">Delete Compare Item</a> — remove one comparison row</li><li><a href="/api/rest-api/shop/compare/delete-all.html">Delete All Compare Items</a> — clear the whole comparison list</li></ul>`,20)]))}const m=t(s,[["render",d]]);export{u as __pageData,m as default};
